python3 -c "
import urllib.request
import ssl
ssl._create_default_https_context = ssl._create_unverified_context

# Try FRED for CPI-U not seasonally adjusted
urls = [
    'https://fred.stlouisfed.org/graph/fredgraph.csv?id=CUUR0000SA0',
]

for url in urls:
    try:
        with urllib.request.urlopen(url, timeout=10) as response:
            content = response.read().decode('utf-8')
            # Look for our dates
            lines = content.split('\n')
            for line in lines:
                if '2000-06' in line or '2000-09' in line or '2001-06' in line or '2001-09' in line or '2002-06' in line or '2002-09' in line or '2003-03' in line:
                    print(line)
    except Exception as e:
        print(f'Error: {e}')
"
